import{_ as o,c as e,o as r,ah as s}from"./chunks/framework.RCw5T9E9.js";const c=JSON.parse('{"title":"About","description":"","frontmatter":{"title":"About"},"headers":[],"relativePath":"ru/options/about.md","filePath":"ru/options/about.md"}'),a={name:"ru/options/about.md"};function n(i,t,l,d,g,h){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p><strong>Options → About</strong> — это раздел с подписью <strong>About</strong>. Настройки инспектора он не меняет.</p><h2 id="vue-inspector" tabindex="-1">Vue Inspector <a class="header-anchor" href="#vue-inspector" aria-label="Permalink to &quot;Vue Inspector&quot;">​</a></h2><p>Текст: <strong>A DevTools extension for inspecting Vue.js applications — components, props, Pinia stores, and network requests.</strong></p><p><strong>Version</strong> показывает версию расширения. Если в манифесте нет версии или версия ровно <code>1.0.0</code>, standalone пишет <code>standalone_latest</code>, а расширение — <code>unknown</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p><strong>Release notes</strong> есть всегда. В расширении загружается релиз GitHub с тегом текущей версии. В standalone загружается последний релиз. Пока идёт загрузка, кнопка недоступна.</p><p><strong>Check for updates</strong> есть только в расширении. Загружается последний релиз, и его тег сравнивается с версией из манифеста. Нет версии в манифесте — сравнение идёт с <code>0.0.0</code>. Более новый тег открывает <strong>Update Available</strong>. Тот же или более старый тег открывает <strong>Up to Date</strong>.</p><p>Карточка закрывается кнопкой назад или Escape.</p><table tabindex="0"><thead><tr><th>Карточка</th><th>Что показывает</th></tr></thead><tbody><tr><td><strong>Release Notes</strong></td><td><strong>Version</strong> и текст заметок. Пустые заметки — <strong>No release notes available.</strong></td></tr><tr><td><strong>Update Available</strong></td><td><strong>Download new version</strong> и номер версии, затем <strong>What&#39;s New</strong>. <strong>Ignore</strong> запоминает эту версию, и всплывающее уведомление об обновлении её пропускает, пока не выйдет другая. <strong>Download</strong> сохраняет первый файл релиза и недоступна, если файла нет</td></tr><tr><td><strong>Up to Date</strong></td><td><strong>You&#39;re up to date!</strong> и <strong>Version … is the latest.</strong> Затем <strong>Current Release Notes</strong>, если у релиза есть заметки</td></tr></tbody></table><p>Неудачный запрос показывает ошибку в карточке. Тексты: <strong>Could not determine current version.</strong>, <strong>No release data available.</strong>, <strong>Failed to fetch release notes.</strong>, <strong>Failed to check for updates.</strong>, <strong>Release not found.</strong>, <strong>GitHub API rate limit exceeded. Resets at …</strong>, <strong>GitHub API error:</strong> и статус, либо <strong>Network error</strong>.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><p><strong>GitHub</strong> открывает <a href="https://github.com/FirsakovAE/qa-tools" target="_blank" rel="noreferrer">https://github.com/FirsakovAE/qa-tools</a>. <strong>Docs</strong> открывает <a href="https://firsakovae.github.io/qa-tools/docs/index.html" target="_blank" rel="noreferrer">https://firsakovae.github.io/qa-tools/docs/index.html</a>.</p><h2 id="footer" tabindex="-1">Footer <a class="header-anchor" href="#footer" aria-label="Permalink to &quot;Footer&quot;">​</a></h2><p><strong>© 2026 FirsakovAE</strong></p><p><strong>GNU General Public License v3.0</strong> открывает <a href="https://www.gnu.org/licenses/gpl-3.0.html" target="_blank" rel="noreferrer">https://www.gnu.org/licenses/gpl-3.0.html</a>.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/releases/history.html">История релизов</a></li><li><a href="/qa-tools/docs/ru/options/display_mode.html">Режимы отображения</a></li></ul>',18)])])}const u=o(a,[["render",n]]);export{c as __pageData,u as default};
